'use client';

import React from 'react';

/** State of the thinking block. */
export type ThinkingBlockState = 'thinking' | 'done' | 'error';

/** Props for the {@link ThinkingBlock} component. */
export interface ThinkingBlockProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Current thinking state. */
  state?: ThinkingBlockState;
  /** Label text displayed in the header. */
  label?: string;
  /** Metadata string (e.g. duration) displayed to the right. */
  meta?: string;
  /** Whether the block is expanded. When undefined, defaults to `true` during thinking. */
  expanded?: boolean;
  /** Default expanded state (uncontrolled). */
  defaultExpanded?: boolean;
  /** Called when the expanded state changes. */
  onExpandedChange?: (expanded: boolean) => void;
  /** Additional CSS class names. */
  className?: string;
  /** Thinking content displayed when expanded. */
  children?: React.ReactNode;
}

/**
 * AI extended thinking block with pulse animation and expand/collapse.
 * Auto-expands while `state` is `"thinking"` and collapses when `"done"`.
 */
export const ThinkingBlock = React.forwardRef<HTMLDivElement, ThinkingBlockProps>(
  (
    {
      state = 'thinking',
      label = 'Thinking...',
      meta,
      expanded: controlledExpanded,
      defaultExpanded,
      onExpandedChange,
      className,
      children,
      ...rest
    },
    ref,
  ) => {
    const [internal, setInternal] = React.useState(defaultExpanded ?? state === 'thinking');
    const isExpanded = controlledExpanded ?? internal;

    // Auto-expand/collapse based on state changes
    React.useEffect(() => {
      if (controlledExpanded !== undefined) return;
      if (state === 'thinking') setInternal(true);
      else if (state === 'done') setInternal(false);
    }, [state, controlledExpanded]);

    const toggle = React.useCallback(() => {
      const next = !isExpanded;
      if (controlledExpanded === undefined) setInternal(next);
      onExpandedChange?.(next);
    }, [isExpanded, controlledExpanded, onExpandedChange]);

    return (
      <div
        ref={ref}
        className={`sk-thinking-block${className ? ` ${className}` : ''}`}
        data-state={state}
        data-expanded={isExpanded ? 'true' : 'false'}
        {...rest}
      >
        <button className="sk-thinking-block__header" onClick={toggle} aria-expanded={isExpanded}>
          <span className="sk-thinking-block__dot" />
          <span className="sk-thinking-block__label">{label}</span>
          {meta && <span className="sk-thinking-block__meta">{meta}</span>}
          <i className="sk-thinking-block__chevron">{'\u25B8'}</i>
        </button>
        {isExpanded && children && (
          <div className="sk-thinking-block__content">{children}</div>
        )}
      </div>
    );
  },
);

ThinkingBlock.displayName = 'ThinkingBlock';

/**
 * skeehn — ThinkingBlock Component
 *
 * @component sk-thinking-block
 * @states    [data-state="thinking"|"done"|"error"] | [data-expanded]
 * @slots     __header __dot __label __meta __chevron __content __token-count
 * @a11y      Button trigger, aria-expanded, focus-visible, reduced motion
 * @design    Mono chrome header, SANS reasoning prose (readable), scroll-fade,
 *            auto-collapse on done (handled in React). Calm pulse, no noise.
 */

.sk-thinking-block {
  border: var(--sk-border);
  border-radius: var(--sk-radius-sm);
  font-family: var(--sk-font-mono);
  position: relative;
  overflow: hidden;
  transition: border-color var(--sk-transition-slow);
}
.sk-thinking-block[data-state="thinking"] { border-color: hsl(var(--sk-accent) / 0.4); }
.sk-thinking-block[data-state="error"]    { border-color: hsl(var(--sk-destructive) / 0.5); }

/* ── Header (mono chrome) ── */
.sk-thinking-block__header {
  display: flex;
  align-items: center;
  gap: var(--sk-space-2);
  padding: var(--sk-space-2) var(--sk-space-3);
  width: 100%;
  cursor: pointer;
  user-select: none;
  border: none;
  text-align: left;
  background: hsl(var(--sk-surface));
  color: hsl(var(--sk-muted-foreground));
  font-family: var(--sk-font-mono);
  font-size: var(--sk-font-size-xs);
  letter-spacing: var(--sk-letter-spacing-wide);
  transition: background var(--sk-transition), color var(--sk-transition);
}
.sk-thinking-block__header:hover { background: hsl(var(--sk-secondary)); color: hsl(var(--sk-foreground)); }
.sk-thinking-block__header:focus-visible { outline: var(--sk-focus-ring); outline-offset: -2px; }

/* ── Status dot ── */
.sk-thinking-block__dot {
  width: 7px;
  height: 7px;
  flex-shrink: 0;
  border-radius: 50%;
  background: hsl(var(--sk-muted-foreground));
}
.sk-thinking-block[data-state="thinking"] .sk-thinking-block__dot {
  background: hsl(var(--sk-accent));
  box-shadow: 0 0 8px hsl(var(--sk-accent) / 0.6);
  animation: sk-thinking-pulse 1.3s ease-in-out infinite;
}
.sk-thinking-block[data-state="done"]  .sk-thinking-block__dot { background: hsl(var(--sk-success)); }
.sk-thinking-block[data-state="error"] .sk-thinking-block__dot { background: hsl(var(--sk-destructive)); }

@keyframes sk-thinking-pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.35; } }

.sk-thinking-block__label  { flex: 1; }
.sk-thinking-block__meta   { font-size: var(--sk-font-size-xs); opacity: 0.6; }
.sk-thinking-block__chevron { font-style: normal; opacity: 0.6; transition: transform var(--sk-transition); }
.sk-thinking-block[data-expanded="true"] .sk-thinking-block__chevron { transform: rotate(90deg); }

/* ── Live token count (readable, tabular) ── */
.sk-thinking-block__token-count {
  font-family: var(--sk-font-mono);
  font-size: var(--sk-font-size-xs);
  color: hsl(var(--sk-muted-foreground) / 0.75);
  letter-spacing: var(--sk-letter-spacing-wide);
  margin-left: auto;
  padding-left: var(--sk-space-2);
  font-variant-numeric: tabular-nums;
}

/* ── Content (SANS reasoning prose, readable, scroll-fade) ── */
.sk-thinking-block__content {
  display: none;
  padding: var(--sk-space-3) var(--sk-space-4);
  border-top: var(--sk-border);
  background: hsl(var(--sk-surface));
  color: hsl(var(--sk-muted-foreground));
  font-family: var(--sk-font-sans);
  font-size: var(--sk-font-size-sm);
  line-height: var(--sk-line-height-relaxed);
  max-height: 320px;
  overflow-y: auto;
  position: relative;
  -webkit-mask-image: linear-gradient(to bottom, transparent 0, #000 var(--sk-space-3), #000 calc(100% - var(--sk-space-4)), transparent 100%);
  mask-image: linear-gradient(to bottom, transparent 0, #000 var(--sk-space-3), #000 calc(100% - var(--sk-space-4)), transparent 100%);
}
.sk-thinking-block[data-expanded="true"] .sk-thinking-block__content { display: block; }

/* Dim live reasoning while thinking; settle on done */
.sk-thinking-block[data-state="thinking"] .sk-thinking-block__content {
  opacity: 0.8;
  transition: opacity var(--sk-transition-slow);
}

/* Subtle scanline texture */
.sk-thinking-block__content::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: var(--sk-dither-scanlines);
  background-size: 100% 4px;
  opacity: var(--sk-dither-opacity-subtle);
  pointer-events: none;
}

/* Blinking caret while actively thinking (single ::after) */
.sk-thinking-block[data-state="thinking"] .sk-thinking-block__content::after {
  content: "▊";
  color: hsl(var(--sk-accent));
  animation: sk-blink 1.1s steps(2) infinite;
}

/* ── Nested thinking (readable, accent rail) ── */
.sk-thinking-block .sk-thinking-block {
  margin: var(--sk-space-2) 0 var(--sk-space-2) var(--sk-space-3);
  border: none;
  border-left: 2px solid hsl(var(--sk-accent) / 0.4);
  border-radius: 0;
}
.sk-thinking-block .sk-thinking-block .sk-thinking-block__header {
  font-size: var(--sk-font-size-xs);
  padding: var(--sk-space-1) var(--sk-space-2);
}

@media print {
  .sk-thinking-block { border: 1px solid hsl(var(--sk-foreground)); }
  .sk-thinking-block__content { display: block; max-height: none; -webkit-mask-image: none; mask-image: none; }
  .sk-thinking-block__content::before, .sk-thinking-block__content::after { display: none; }
  .sk-thinking-block__dot { animation: none; }
  .sk-thinking-block__chevron { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .sk-thinking-block__dot { animation: none; }
  .sk-thinking-block__content::after { animation: none; }
  .sk-thinking-block__chevron, .sk-thinking-block__header { transition: none; }
}
